/*
 * Reconcile what docs/API_CONTRACT.md promises with what the running service declares.
 *
 * The drift ledger (`check_contract_drift.mjs`) answers "does any client call this?" by searching source
 * for path literals. That question is necessary and not sufficient: a route can be named in a handler's
 * Javadoc, or matched by a substring, and still not be reachable. `/v3/api-docs` is the opposite kind of
 * evidence — it is generated by the annotations the router actually registered, in the process actually
 * answering, from the build actually checked out. Comparing the contract against it turns
 * "I believe §6 is mostly served" into a list with two lengths.
 *
 * Usage: node scripts/verify_contract_runtime.mjs --base http://127.0.0.1:8092
 *        (point it at `scripts/e2e_fresh.sh --keep`, not at a stale instance — the document describes
 *         the build it came from)
 * Exit 1 if a *read* documented in the phase-1 consumer sections (§4 catalog, §8 growth/creator) is not
 * declared by the service — that is a page a consumer can be sent to with nothing behind it. Everything
 * else is reported rather than judged: the contract also documents workspace, admin and later-phase
 * surfaces, and an absent one of those is a roadmap fact. A documented *write* that is unbuilt is a
 * decision (D34 keeps §8's POST unbuilt), so it is listed and not failed on.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONTRACT = path.join(ROOT, 'docs', 'API_CONTRACT.md');
const argv = process.argv.slice(2);
const arg = (n, f) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : f; };
const BASE = arg('base', 'http://127.0.0.1:8090').replace(/\/$/, '');

const VERBS = '(?:GET|POST|PATCH|PUT|DELETE|HEAD|OPTIONS)';

/**
 * The contract writes an optional id as `…/offerings[/{id}]`, which documents one route with two
 * spellings — the collection form and the item form. Collapsing the brackets to the base and then
 * reporting the item route as "not served" is a reading error, not a gap, so the bracket expands to
 * every form the notation permits and a documented route counts as served when *any* of them answers.
 */
function forms(rawPath) {
  const m = rawPath.match(/^([^\[]*)\[([^\]]*)\](.*)$/);
  if (!m) return [rawPath];
  const [, base, opt, tail] = m;
  return [`${base}${tail}`, `${base}${opt}${tail}`].filter((v, i, a) => a.indexOf(v) === i);
}

/**
 * `{a|b}` in a *path* is several routes written compactly, and each of them is a separate promise.
 *
 * `norm` below collapses a `{…}` group to `{}` because a parameter is a hole — `/users/{id}` and
 * `/users/{slug}` are the same handler. An alternation is the opposite: `{users|merchants}` names two
 * literal paths, so collapsing it into one `{}` both retires the second promise and invents a first one
 * (`/admin/{}`, a path no router can hold). Split before that happens, then recurse so `{a|b|c…}` of any
 * length works. `[…]` by contrast really is one route with two spellings, and stays with `forms`.
 */
function alternatives(rawPath) {
  const m = rawPath.match(/\{([^{}|]*(?:\|[^{}|]*)+)\}/);
  if (!m) return [rawPath];
  const head = rawPath.slice(0, m.index);
  const tail = rawPath.slice(m.index + m[0].length);
  return m[1].split('|').flatMap((a) => alternatives(`${head}${a}${tail}`));
}

/** A `{param}` is a hole, not a value: every parameterised path reads as one shape on both sides. */
const norm = (p) => p.replace(/\{[^}]*\}/g, '{}').replace(/\/+$/, '').replace(/\?.*$/, '');

/**
 * Read the contract in the notation it is actually written in.
 *
 * A method cell names several verbs (`GET/POST/DELETE`); a row then names several paths separated by the
 * middle dot, some of them relative to the `/api/v1` prefix (`` | GET | `/api/v1/me/orders` · `/me/…` ``);
 * a span can carry its own verb (`` POST `/api/v1/notifications/{id}/read` ``); and a span can continue
 * past the path into a body sketch (`` POST /api/v1/events {events:[…]} ``). Taking only the first verb
 * of a cell, or only a span that is exactly a path, quietly un-documents all of those — which is what the
 * first two parses did, in opposite directions: one defaulted every bare span to GET and reported 63
 * phantom gaps, the other saw one verb per row and reported 26 gaps that were mostly this. An inventory
 * that cannot read its own source reports its blindness as somebody else's documentation hole.
 */
function documented() {
  const rows = [];
  let section = 0;
  const text = readFileSync(CONTRACT, 'utf8').replace(/\r\n/g, '\n');
  for (const line of text.split('\n')) {
    const heading = line.match(/^##\s+(\d+)/);
    if (heading) section = Number(heading[1]);
    const cell = line.match(new RegExp('^\\|\\s*(?:' + VERBS + ')(?:/(?:' + VERBS + '))*\\s*\\|', 'i'));
    const verbs = cell ? cell[0].replace(/\||\s/g, '').toUpperCase().split('/') : [];
    let rowBase = null;
    const push = (method, rawPath) => {
      // Split on whitespace, because a body sketch follows the path (`POST /api/v1/events {events:[…]}`).
      // Not on `[` — that is where the contract's optional-id shorthand (`…/offerings[/{id}]`) used to be
      // cut off, which left `forms()` with nothing to expand and reported three served item routes as
      // "served, not documented" while inventing a DELETE on their collection. Not on `{` either: that is
      // how every parameterised route once came to be truncated to its prefix, turning 26 gaps into 47.
      let p = rawPath.split(/\s+/)[0].replace(/[.,;]$/, '');
      if (/^\/api\/v1\b/.test(p) || /^\/ai\/v1\b/.test(p) || /^\/\.?well-known\b/.test(p)) {
        if (/^\/api\/v1\b/.test(p)) rowBase = p;      // later spans may hang off this one
        if (p.startsWith('/well-known')) p = `/.${p.slice(1)}`;   // the document writes the host root with its dot
        rows.push({ method, raw: p, section });
      } else if (/^\/(me|merchant|merchants|admin|ai|notifications)\b/.test(p) && verbs.length) {
        rows.push({ method, raw: `/api/v1${p}`, section });
      } else if (/^\/\{/.test(p) && rowBase) {
        // A continuation: `` POST `/{id}/reply` `` on the row whose first path is
        // `/api/v1/merchant/conversations`. Relative to that base, not to the API root — and it is only a
        // route at all because the verb in front of it says so.
        rows.push({ method, raw: `${rowBase}${p}`, section });
      }
      // anything else (`/api/nexus/**`, prose) is a proxy or a sentence, not a service route
    };
    // Walk the spans, keeping the text between them: a verb written *outside* the backticks
    // (`· POST \`/api/v1/me/favorites\``) belongs to the span that follows it, and used to be discarded —
    // which both lost that POST and left the row's own verb attached to every other span, inventing a
    // `GET /api/v1/me/favorites/{type}/{id}` nobody promised. `own` below is the same notation with the
    // verb inside the span, which the reader has always honoured.
    const spanRe = /`[^`\n]+`/g;
    let hit;
    while ((hit = spanRe.exec(line))) {
      const lead = line.slice(0, hit.index).match(new RegExp('(?:^|[^\\w|])(' + VERBS + ')[\\s·]*$', 'i'));
      const body = hit[0].slice(1, -1).trim();
      const own = body.match(new RegExp('^(' + VERBS + ')\\s+(\\S.*)$', 'i'));
      if (own) { push(own[1].toUpperCase(), own[2]); continue; }
      if (body.startsWith('/')) for (const v of (lead ? [lead[1].toUpperCase()] : verbs)) push(v, body);
    }
  }
  // One documented route, keyed by method and its *written* form, holding every path spelling the
  // notation permits. `served` is then "at least one spelling answers" — which is right for an optional
  // `[/{id}]` suffix and wrong for a `{users|merchants}` alternation, so the alternation is split into
  // separate routes here and each of them has to answer on its own.
  const seen = new Map();
  for (const r of rows) {
    for (const raw of alternatives(r.raw)) {
      const written = norm(raw);
      const spellings = forms(raw).map(norm).filter((p) => p.length >= 8 && !p.includes('*'));
      if (!spellings.length) continue;                 // `/api/v1/**` is a BFF mount, not a handler
      const key = `${r.method} ${written.replace(/\[[^\]]*\]/g, '')}`;
      const row = seen.get(key) ?? { ...r, spellings: new Set() };
      for (const p of spellings) row.spellings.add(p);
      seen.set(key, row);
    }
  }
  return [...seen.values()].map((r) => ({ ...r, path: [...r.spellings][0], spellings: [...r.spellings] }));
}

async function served() {
  const res = await fetch(`${BASE}/v3/api-docs`, { headers: { Accept: 'application/json' } });
  if (!res.ok) throw new Error(`/v3/api-docs answered HTTP ${res.status} from ${BASE}`);
  const doc = await res.json();
  const out = new Set();
  for (const [p, ops] of Object.entries(doc.paths ?? {})) {
    for (const method of Object.keys(ops)) out.add(`${method.toUpperCase()} ${norm(p)}`);
  }
  return out;
}

const PHASE1 = new Set([4, 8]);
try {
  const docs = documented();
  const live = await served();
  const answers = (d) => d.spellings.some((p) => live.has(`${d.method} ${p}`));
  // The host-root profile is a route the service declares and UCP discovery fetches, so it is in scope for
  // the reconciliation like any `/api/v1` path — reporting it as undocumented is only ever noise.
  const inScope = (p) => p.startsWith('/api/v1') || p.startsWith('/.well-known');
  const scope = docs.filter((d) => inScope(d.path));
  const matched = scope.filter(answers);
  const missing = scope.filter((d) => !answers(d));
  const hardMissing = missing.filter((d) => PHASE1.has(d.section) && d.method === 'GET');

  console.log(`contract routes in scope : ${scope.length} of ${docs.length} documented`);
  console.log(`declared by the service  : ${matched.length}`);
  console.log(`documented, not served   : ${missing.length}`
    + (hardMissing.length ? `  (${hardMissing.length} of them a phase-1 §4/§8 read)` : ''));
  const bySection = new Map();
  for (const m of missing) {
    const k = Number(m.section);
    bySection.set(k, (bySection.get(k) ?? []).concat(`${m.method} ${m.path}`));
  }
  for (const [k, list] of [...bySection].sort((a, b) => a[0] - b[0])) {
    console.log(`  §${String(k).padEnd(6)} ${list.join(', ')}`);
  }
  const documentedAny = new Set(scope.flatMap((d) => d.spellings.map((p) => `${d.method} ${p}`)));
  const undocumented = [...live].filter((l) => !documentedAny.has(l));
  console.log(`served, not documented   : ${undocumented.length}`);
  for (const u of undocumented.sort()) console.log(`  · ${u}`);
  if (undocumented.length) {
    console.log('  before "fixing" any of these, read the §-tables: this parser has been wrong twice,');
    console.log('  and a hole in the reader looks exactly like a hole in the document.');
  }

  if (hardMissing.length) {
    console.log('\nRESULT: FAIL — a phase-1 §4/§8 read is documented and not served');
    for (const m of hardMissing) console.log(`  - ${m.method} ${m.path}`);
    process.exit(1);
  }
  console.log('\nRESULT: PASS — every documented phase-1 §4/§8 read is declared by the running service');
} catch (err) {
  console.log(`cannot reconcile: ${err.message}`);
  console.log('start one with:  bash scripts/e2e_fresh.sh --keep');
  process.exit(2);
}
